/// <reference types="@rbxts/types" />
export default class BezierCurve<T extends {
    Lerp(this: T, other: T, fraction: number): T;
}, P extends Array<T>> {
    private points;
    /**
     * @param points Array with input points.
     */
    constructor(points: [...P, P[0] extends undefined ? T : T & P[0]]);
    /**
     * Calculates a point on the curve.
     * @param n The fraction to calculate with.
     */
    calculate(n: number): T;
    /**
     * Calculates one step.
     * Returns an Array of length 1 smaller than the input Array.
     * @param n The fraction to calculate with.
     */
    getPoints(n: number): P;
    private getPointsInternal;
}
